import { Inject, Injectable, Logger, forwardRef } from '@nestjs/common';
import { CustomerService } from '../customer/customer.service';
import { InfluxService } from '../influx/influx.service';
import { InvoicesService } from '../invoice/invoices.service';
import { Billing, billingScheduleConsumers } from './entities/billing.entity';
import { randomUUID } from 'crypto';
import { Process, Processor } from '@nestjs/bull';
import { CreateBillingReportDto } from './dto/createBillingReport.dto';
import { Job } from 'bull';
import { SchedulerEntity } from '../scheduler/entities/scheduler.entity';
import { AuditService } from '../audit/audit.service';
import { AuditScope } from '../audit/entities/audit.interface';
import { CustomerEntity } from '../customer/entities/customer.entity';
import { OfferingService } from '../offering/offering.service';

@Processor('scheduler_billing_queue')
export class BillingService {
    private static readonly logger = new Logger(BillingService.name);
    constructor(
        readonly InfluxService: InfluxService,
        @Inject(forwardRef(() => CustomerService)) readonly customerService: CustomerService,
        @Inject(forwardRef(() => InvoicesService)) readonly invoicesService: InvoicesService,
        @Inject(forwardRef(() => OfferingService)) readonly offeringService: OfferingService
    ) {}
    @Process({ name: billingScheduleConsumers.billingReport })
    async create({ data: { scheduleParameters } }: Job<SchedulerEntity>) {
        const { customerId, businessID } = scheduleParameters as CreateBillingReportDto;
        try {
            // 1. Resolve the customer and its offering
            const customerResponse = await this.customerService.findOne({ customerId, businessID });
            const customerData = customerResponse.data[0];
            const customerEntity = new CustomerEntity(customerData);

            if (!customerEntity.offeringId) {
                BillingService.logger.log(`Customer ${customerId} has no offering, skipping billing`);
                return;
            }

            // 2. Derive the offering billing-cycle time range
            const offeringResponse = await this.offeringService.findOne({ businessID, offeringId: customerEntity.offeringId });
            const offering = offeringResponse.data[0];
            const { startTime, endTime } = Billing.billingCycleToTimeRange(offering.billingCycle);

            // 3. Call the existing usage-total invoice path with that exact customer and range
            const { invoiceId } = await this.invoicesService.generateInvoiceForUsageTotal({
                businessID,
                customerId,
                start: startTime,
                end: endTime,
            });

            // 4. Persist a billing record containing the returned invoice ID
            const entity = new Billing({
                invoiceId,
                businessID,
                customerId,
                startTime,
                endTime,
                billingId: randomUUID(),
            });
            const point = Billing.transformer(entity, this.InfluxService);
            await this.InfluxService.loadPoints(`${process.env.STAGE}-aggregate-usage`, 'paigo', [point]);
            BillingService.logger.log(`Billing record created for customer ${customerId} with invoice ${invoiceId}`);
        } catch (error) {
            // 5. Report processing failures through the existing audit channel
            AuditService.publishEvent({
                message: `Billing processing failed for customer ${customerId} in business ${businessID}`,
                topic: AuditScope.ERROR,
                data: [error],
            });
            throw error;
        }
    }
}

